-- ========================================================
-- NEXA Intelligence POC - Supabase PostgreSQL Schema & Seed
-- Target Organization: Financiera Comultrasan
-- ========================================================

-- Enable UUID extension if not present
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. ORGANIZATIONS
CREATE TABLE IF NOT EXISTS organizations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    type TEXT NOT NULL,
    country TEXT NOT NULL DEFAULT 'Colombia',
    city TEXT NOT NULL DEFAULT 'Bucaramanga',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 2. PEOPLE
CREATE TABLE IF NOT EXISTS people (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    document_type TEXT NOT NULL DEFAULT 'CC',
    document_number TEXT NOT NULL,
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL,
    email TEXT,
    phone TEXT,
    birth_date DATE,
    age INTEGER,
    gender TEXT,
    city TEXT,
    department TEXT,
    employment_status TEXT,
    occupation TEXT,
    education_level TEXT,
    characterization_score INTEGER NOT NULL DEFAULT 0,
    profile_status TEXT NOT NULL DEFAULT 'Parcial',
    contactable BOOLEAN NOT NULL DEFAULT true,
    inclusion_information_status TEXT NOT NULL DEFAULT 'Pendiente',
    last_interaction_at TIMESTAMPTZ,
    member_since INTEGER,
    segment TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 3. EXTENSIBLE PERSON ATTRIBUTES
CREATE TABLE IF NOT EXISTS person_attributes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    person_id UUID NOT NULL REFERENCES people(id) ON DELETE CASCADE,
    category TEXT NOT NULL,
    attribute_key TEXT NOT NULL,
    attribute_value TEXT NOT NULL,
    source TEXT DEFAULT 'Core financiero',
    confidence NUMERIC(4, 2) DEFAULT 1.00,
    verified BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 4. CAMPAIGNS
CREATE TABLE IF NOT EXISTS campaigns (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    status TEXT NOT NULL DEFAULT 'Activa',
    audience_count INTEGER NOT NULL DEFAULT 0,
    contacted_count INTEGER NOT NULL DEFAULT 0,
    responded_count INTEGER NOT NULL DEFAULT 0,
    completed_count INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 5. CAMPAIGN TARGETS
CREATE TABLE IF NOT EXISTS campaign_targets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
    person_id UUID NOT NULL REFERENCES people(id) ON DELETE CASCADE,
    channel TEXT NOT NULL DEFAULT 'whatsapp',
    status TEXT NOT NULL DEFAULT 'Sin contactar',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(campaign_id, person_id)
);

-- 6. INTERACTIONS (Designed for future AI characterization)
CREATE TABLE IF NOT EXISTS interactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    person_id UUID NOT NULL REFERENCES people(id) ON DELETE CASCADE,
    campaign_id UUID REFERENCES campaigns(id) ON DELETE SET NULL,
    channel TEXT NOT NULL DEFAULT 'WEB',
    direction TEXT NOT NULL DEFAULT 'OUTBOUND',
    status TEXT NOT NULL DEFAULT 'COMPLETED',
    summary TEXT,
    structured_data JSONB DEFAULT '{}'::jsonb,
    ai_generated BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 7. CONSENTS (Habeas Data / Ley 1581)
CREATE TABLE IF NOT EXISTS consents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    person_id UUID NOT NULL REFERENCES people(id) ON DELETE CASCADE,
    consent_type TEXT NOT NULL DEFAULT 'Ley 1581 / Tratamiento de Datos',
    status TEXT NOT NULL DEFAULT 'Otorgada',
    source TEXT NOT NULL DEFAULT 'Oficina',
    captured_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- INDEXES
CREATE INDEX IF NOT EXISTS idx_people_org ON people(organization_id);
CREATE INDEX IF NOT EXISTS idx_people_city ON people(city);
CREATE INDEX IF NOT EXISTS idx_people_status ON people(profile_status);
CREATE INDEX IF NOT EXISTS idx_people_score ON people(characterization_score);
CREATE INDEX IF NOT EXISTS idx_people_doc ON people(document_number);
CREATE INDEX IF NOT EXISTS idx_person_attributes_person ON person_attributes(person_id);
CREATE INDEX IF NOT EXISTS idx_person_attributes_cat_key ON person_attributes(category, attribute_key);
CREATE INDEX IF NOT EXISTS idx_campaign_targets_camp ON campaign_targets(campaign_id);
CREATE INDEX IF NOT EXISTS idx_campaign_targets_person ON campaign_targets(person_id);
CREATE INDEX IF NOT EXISTS idx_interactions_person ON interactions(person_id);
CREATE INDEX IF NOT EXISTS idx_consents_person ON consents(person_id);

-- ROW LEVEL SECURITY (RLS)
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE people ENABLE ROW LEVEL SECURITY;
ALTER TABLE person_attributes ENABLE ROW LEVEL SECURITY;
ALTER TABLE campaigns ENABLE ROW LEVEL SECURITY;
ALTER TABLE campaign_targets ENABLE ROW LEVEL SECURITY;
ALTER TABLE interactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE consents ENABLE ROW LEVEL SECURITY;

-- POC Public Policies (Safe access for unauthenticated POC client)
DO $$
BEGIN
    DROP POLICY IF EXISTS "POC public organizations" ON organizations;
    CREATE POLICY "POC public organizations" ON organizations FOR ALL USING (true) WITH CHECK (true);
    
    DROP POLICY IF EXISTS "POC public people" ON people;
    CREATE POLICY "POC public people" ON people FOR ALL USING (true) WITH CHECK (true);
    
    DROP POLICY IF EXISTS "POC public person_attributes" ON person_attributes;
    CREATE POLICY "POC public person_attributes" ON person_attributes FOR ALL USING (true) WITH CHECK (true);
    
    DROP POLICY IF EXISTS "POC public campaigns" ON campaigns;
    CREATE POLICY "POC public campaigns" ON campaigns FOR ALL USING (true) WITH CHECK (true);
    
    DROP POLICY IF EXISTS "POC public campaign_targets" ON campaign_targets;
    CREATE POLICY "POC public campaign_targets" ON campaign_targets FOR ALL USING (true) WITH CHECK (true);
    
    DROP POLICY IF EXISTS "POC public interactions" ON interactions;
    CREATE POLICY "POC public interactions" ON interactions FOR ALL USING (true) WITH CHECK (true);
    
    DROP POLICY IF EXISTS "POC public consents" ON consents;
    CREATE POLICY "POC public consents" ON consents FOR ALL USING (true) WITH CHECK (true);
END $$;

